import 'package:flutter/material.dart';
import 'package:youtube_explode_dart/youtube_explode_dart.dart' as yte;
import 'package:youtube_player_iframe/youtube_player_iframe.dart';

void main() => runApp(const RockApp());

class RockApp extends StatelessWidget {
  const RockApp({super.key});

    @override
      Widget build(BuildContext context) {
          return MaterialApp(
                title: 'Rock',
                      debugShowCheckedModeBanner: false,
                            theme: ThemeData(
                                    brightness: Brightness.dark,
                                            colorSchemeSeed: Colors.redAccent,
                                                    useMaterial3: true,
                                                          ),
                                                                home: const Home(),
                                                                    );
                                                                      }
                                                                      }

                                                                      class Home extends StatefulWidget {
                                                                        const Home({super.key});

                                                                          @override
                                                                            State<Home> createState() => _HomeState();
                                                                            }

                                                                            class _HomeState extends State<Home> {
                                                                              final yt = yte.YoutubeExplode();
                                                                                final controller = TextEditingController();
                                                                                  YoutubePlayerController? player;

                                                                                    static const generos = [
                                                                                        'Rock clásico',
                                                                                            'Rock alternativo',
                                                                                                'Rock en español',
                                                                                                    'Indie rock',
                                                                                                        'Punk rock',
                                                                                                            'Hard rock',
                                                                                                                'Metal',
                                                                                                                    'Grunge',
                                                                                                                      ];

                                                                                                                        List<yte.Video> results = [];
                                                                                                                          int current = -1;
                                                                                                                            bool loading = false;
                                                                                                                              String? error;

                                                                                                                                @override
                                                                                                                                  void initState() {
                                                                                                                                      super.initState();
                                                                                                                                          search('Rock clásico');
                                                                                                                                            }

                                                                                                                                              @override
                                                                                                                                                void dispose() {
                                                                                                                                                    player?.close();
                                                                                                                                                        yt.close();
                                                                                                                                                            controller.dispose();
                                                                                                                                                                super.dispose();
                                                                                                                                                                  }

                                                                                                                                                                    Future<void> search(String q) async {
                                                                                                                                                                        if (q.trim().isEmpty) return;
                                                                                                                                                                            setState(() {
                                                                                                                                                                                  loading = true;
                                                                                                                                                                                        error = null;
                                                                                                                                                                                            });
                                                                                                                                                                                                try {
                                                                                                                                                                                                      final low = q.toLowerCase();
                                                                                                                                                                                                            final query = low.contains('rock') ||
                                                                                                                                                                                                                          low.contains('metal') ||
                                                                                                                                                                                                                                        low.contains('grunge')
                                                                                                                                                                                                                                                  ? q
                                                                                                                                                                                                                                                            : '$q rock';
                                                                                                                                                                                                                                                                  final list = await yt.search.search(query);
                                                                                                                                                                                                                                                                        final filtered = list
                                                                                                                                                                                                                                                                                  .where((v) =>
                                                                                                                                                                                                                                                                                                !v.isLive && v.duration != null && v.duration!.inMinutes < 12)
                                                                                                                                                                                                                                                                                                          .toList();
                                                                                                                                                                                                                                                                                                                setState(() {
                                                                                                                                                                                                                                                                                                                        results = filtered;
                                                                                                                                                                                                                                                                                                                                current = -1;
                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                          } catch (e) {
                                                                                                                                                                                                                                                                                                                                                setState(() => error = 'Error al buscar: $e');
                                                                                                                                                                                                                                                                                                                                                    } finally {
                                                                                                                                                                                                                                                                                                                                                          setState(() => loading = false);
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                     void playAt(int i) {
    if (i < 0 || i >= results.length) return;
    final id = results[i].id.value;
    setState(() => current = i);
    final p = player;
    if (p == null) {
      final c = YoutubePlayerController.fromVideoId(
        videoId: id,
        autoPlay: true,
        params: const YoutubePlayerParams(
          origin: 'https://com.hernan.rock_app',
          showFullscreenButton: true,
        ),
      );
      c.listen((e) {
        if (e.playerState == PlayerState.ended &&
            current + 1 < results.length) {
          playAt(current + 1);
        }
      });
      setState(() => player = c);
    } else {
      p.loadVideoById(videoId: id);
    }
  }

  String fmt(Duration d) {
    final m = d.inMinutes.remainder(60).toString();
    final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
    return '$m:$s';
  }     

     @override
       Widget build(BuildContext context) {
           return Scaffold(
                 appBar: AppBar(title: const Text('🤘 Rock')),
                       body: Column(
                               children: [
                                         if (player != null)
                                                     YoutubePlayer(controller: player!, aspectRatio: 16 / 9),
                                                               Padding(
                                                                           padding: const EdgeInsets.fromLTRB(12, 8, 12, 4),
                                                                                       child: TextField(
                                                                                                     controller: controller,
                                                                                                                   textInputAction: TextInputAction.search,
                                                                                                                                 onSubmitted: search,
                                                                                                                                               decoration: InputDecoration(
                                                                                                                                                               hintText: 'Busca una banda o canción',
                                                                                                                                                                               prefixIcon: const Icon(Icons.search),
                                                                                                                                                                                               border: OutlineInputBorder(
                                                                                                                                                                                                                 borderRadius: BorderRadius.circular(28),
                                                                                                                                                                                                                                 ),
                                                                                                                                                                                                                                               ),
                                                                                                                                                                                                                                                           ),
                                                                                                                                                                                                                                                                     ),
                                                                                                                                                                                                                                                                               SizedBox(
                                                                                                                                                                                                                                                                                           height: 48,
                                                                                                                                                                                                                                                                                                       child: ListView.separated(
                                                                                                                                                                                                                                                                                                                     scrollDirection: Axis.horizontal,
                                                                                                                                                                                                                                                                                                                                   padding: const EdgeInsets.symmetric(horizontal: 12),
                                                                                                                                                                                                                                                                                                                                                 itemCount: generos.length,
                                                                                                                                                                                                                                                                                                                                                               separatorBuilder: (_, __) => const SizedBox(width: 8),
                                                                                                                                                                                                                                                                                                                                                                             itemBuilder: (_, i) => ActionChip(
                                                                                                                                                                                                                                                                                                                                                                                             label: Text(generos[i]),
                                                                                                                                                                                                                                                                                                                                                                                                             onPressed: () {
                                                                                                                                                                                                                                                                                                                                                                                                                               controller.text = generos[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                 search(generos[i]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (loading) const LinearProgressIndicator(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (error != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   padding: const EdgeInsets.all(12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 child: Text(error!,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   style: const TextStyle(color: Colors.redAccent)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         Expanded(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     child: ListView.builder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   itemCount: results.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 itemBuilder: (_, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 final v = results[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return ListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   selected: i == current,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     leading: ClipRRect(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         borderRadius: BorderRadius.circular(6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             child: Image.network(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   v.thumbnails.lowResUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         width: 56,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               height: 56,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     fit: BoxFit.cover,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           errorBuilder: (_, __, ___) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const Icon(Icons.music_note, size: 40),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             title: Text(v.title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   maxLines: 2, overflow: TextOverflow.ellipsis),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     subtitle: Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         '${v.author} · ${fmt(v.duration ?? Duration.zero)}',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             maxLines: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 overflow: TextOverflow.ellipsis,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     onTap: () => playAt(i),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (current >= 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               SafeArea(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             top: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           child: Row(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             IconButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 icon: const Icon(Icons.skip_previous),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     onPressed: current > 0 ? () => playAt(current - 1) : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         IconButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             icon: const Icon(Icons.skip_next),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 onPressed: current + 1 < results.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ? () => playAt(current + 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }                                                                       